"""Assemble reviewable trial statistics without changing official records."""
import hashlib,json,platform,subprocess,sys
from pathlib import Path
from datetime import datetime,timezone
D=Path(__file__).resolve().parent;ROOT=D.parents[1]
def load(p):return json.loads(p.read_text())
def put(name,obj):(D/name).write_text(json.dumps(obj,indent=2)+'\n')
t=load(D/'TRIAL.json');rows=load(D/'starting-frontier.json');c=load(D/'candidates.json');events=[json.loads(x) for x in (D/'events.jsonl').read_text().splitlines()];wins=[e for e in events if e['event']=='verified_improvement'];bounds=load(D/'bound-results.json')['bounds'];candidate={(r['graph'],r['budget']):r for r in c};lower={(r['graph'],r['budget']):r['lower_bound'] for r in rows}
for b in bounds:lower[b['graph'],b['budget']]=max(lower[b['graph'],b['budget']],b['lower_bound'])
work=[r for r in rows if r['family']!='synthetic']
# Family names are checked by exact-bound status; tiny cells have exact-minimax bounds.
work=[r for r in rows if r['bound_method']!='exact-minimax']
remaining=[];closed=[]
for r in work:
    key=(r['graph'],r['budget']);best=candidate.get(key,r);lb=lower[key]
    if best['peak_bytes']>lb:
        remaining.append({'id':f"{r['graph']}-b{r['budget']}",'graph':r['graph'],'budget':r['budget'],'peak_bytes':best['peak_bytes'],'lower_bound':lb,'gap_bytes':best['peak_bytes']-lb,'certificate':best['object'],'first_step':'Replay certificate, then improve scheduling or prove a stronger lower bound. A positive bound gap is not evidence that an improvement exists.'})
    elif not r['optimal']:closed.append({'graph':r['graph'],'budget':r['budget'],'peak_bytes':best['peak_bytes'],'type':'improved-schedule-matches-bound' if key in candidate else 'stronger-bound'})
attempts=[]
for p in sorted(D.glob('cache-attempts-*.json')):attempts+=load(p)
if (D/'focused-attempts.json').exists():attempts+=load(D/'focused-attempts.json')
selected=t['selected_row'];sw=[e for e in wins if (e['graph'],e['budget'])==(selected['graph'],selected['budget'])]
stats={'base_commit':t['base_commit'],'started_at':t['started_at'],'deadline':t['deadline'],'wall_budget_seconds':1800,'generated_at':datetime.now(timezone.utc).isoformat(),'workload_cells':len(work),'initial_open_workload_cells':sum(not r['optimal'] for r in work),'improved_cells':len(c),'improved_graphs':len({r['graph'] for r in c}),'historical_verified_improvements':len(wins),'first_any_improvement_seconds':min(e['verified_at_seconds'] for e in wins),'first_selected_improvement_seconds':min(e['verified_at_seconds'] for e in sw),'last_improvement_seconds':max(e['verified_at_seconds'] for e in wins),'selected_start_peak':selected['peak_bytes'],'selected_final_peak':candidate[selected['graph'],selected['budget']]['peak_bytes'],'max_peak_reduction_percent':max(100*(1-r['peak_bytes']/r['starting_peak']) for r in c),'checkpoint_policies_evaluated':sum(e['evaluated'] for e in events if e['event']=='search_end'),'adaptive_policies_attempted':len(attempts),'adaptive_policies_legal':sum(a['status']=='legal' for a in attempts),'newly_closed_cells':closed,'remaining_open_cells':len(remaining),'python':sys.version,'platform':platform.platform(),'evidence_level':'author-checked','fresh_verifier_process_on_every_improvement':True,'blind_newcomer_trial':False,'gpu_validation':False}
put('summary.json',stats);put('remaining-tasks.json',remaining)
put('TASK.json',{'card':'none','catalog_revision':load(ROOT/'discover/catalog.json')['priority_revision'],'scope':'30-minute LOCAL donor-yield trial against frozen graph/budget records; random initial cell, checkpoint and adaptive cache search, transfer, bounds and replay','scope_status':'unchanged','budget_minutes':30,'outcome':'positive','evidence_level':'author-checked','not_checked':['Independent reviewer acceptance','Blind newcomer yield','GPU execution','Sustained yield across unrelated workloads','Comparison against imported modern optimal solver schedules'],'next_questions':[{'question':'Do independent newcomers improve the updated frontier?','why_it_matters':'Author familiarity and consumed easy wins limit this trial.','first_step':'Freeze the proposed updated records and assign three independent 30-minute trials on remaining-tasks.json.','blocked_by':'Independent contributors and review of this candidate package'},{'question':'Does yield persist on more varied realistic graphs?','why_it_matters':'Five successful graphs come from only two template families.','first_step':'Add versioned graph exports with varied shapes, mixed branches and explicit operator semantics, and modern-solver baselines.','blocked_by':'Model/export fidelity review'}],'credit':['Codex local trial'],'ai_assistance':'Single continuing author agent; no subagents.'})
files=['verifier.py','search.py','MODEL.md','records/frontiers.json','benchmarks/manifest.json']
put('SOURCES.json',{'base_commit':t['base_commit'],'git_blob_ids':{p:subprocess.check_output(['git','rev-parse',t['base_commit']+':'+p],text=True).strip() for p in files if (ROOT/p).exists()},'core_sha256':{p:hashlib.sha256((ROOT/p).read_bytes()).hexdigest() for p in files if (ROOT/p).exists()},'trial_sources_sha256':{p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(D.glob('*.py'))},'frozen_graphs_sha256':{p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted((ROOT/'benchmarks/graphs').glob('*.json'))}})
put('VERIFY.json',{'cwd':'repository root','commands':[['python3','research/trial-30m/verify_trial.py','--reconstruct'],['python3','research/trial-30m/test_trial.py'],['python3','research/trial-30m/check_bounds.py'],['python3','verify_all.py']],'timeout_seconds_per_command':120,'dependencies':{'python':'>=3.9; tested 3.12.8 and 3.14.6','external_packages':[]},'inputs':['SOURCES.json','TRIAL.json','starting-frontier.json','candidates.json','certificates/','events.jsonl'],'expected':'All PASS; candidate actions reconstruct exactly; all 25 tiny exact optima match; official frontier unchanged.','bound_warning':'The schedule checker verifies feasibility, not lower bounds. check_bounds.py recomputes the proposed proof claims.','no_training_required':True})
print(json.dumps(stats,indent=2))
